entries[73461] = { ["name"] = "Vampirnachtsauer zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit der Zähmung eines Vampirnachtsaugers, damit er 15 Min. lang Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl." }
